GEARS = {
 'A8': [('Aw',24,0.2,(0.1,0.6)),('Ap',40,0.25,LAYER(1))],
 'A6': [('Aw',32,0.2,(0.1,0.6)),('Ap',40,0.25,LAYER(1))],
