 'I':  [('Iw',45,0.2,LAYER(2)),('Ip',12,0.2,LAYER(4))],
 'H':  [('Hw',48,0.2,LAYER(4)),('Hg',24,0.2,LAYER(5))],
 'J':  [('Jw',24,0.2,LAYER(5))],
 'D':  [('Dg',48,0.2,LAYER(5))],
 'X1': [('X1p',12,0.2,LAYER(3)),('X1w',36,0.2,LAYER(6))],
 'X2': [('X2p',12,0.2,LAYER(6)),('X2w',48,0.2,LAYER(7))],
 'X3': [('X3p',12,0.2,LAYER(7)),('X3w',24,0.2,LAYER(8))],
 'S':  [('Sp',12,0.2,LAYER(8))],
}
# meshes: (driver, gear, driven, gear)
MESH = [('A8','Ap','M','Mg'),('M','Mp','I','Iw'),('I','Ip','H','Hw'),('H','Hg','J','Jw'),('J','Jw','D','Dg'),
        ('M','Mg2','X1','X1p'),('X1','X1w','X2','X2p'),('X2','X2w','X3','X3p'),('X3','X3w','S','Sp')]
