    cs.append((x,y,RA,-1.2,top,'arbor'))
    if name=='H': cs.append((x,y,1.1,2.85,STAFF_TOP['H'],'tube'))
    if name!='H': cs.append((x,y,1.0,0.0,0.5,'boss'))
    if name not in ('M','H','A8','A6','S'): cs.append((x,y,1.0,ZB-0.55,ZB-0.05,'collar'))
    if name in ('A8','A6'): cs.append((x,y,1.0,ZB-0.55,ZB-0.05,'collar'))
    if name=='H': cs.append((x,y,1.6,ZB-0.55,ZB-0.05,'collar'))
    for g,z,m,(z0,z1) in [(g[0],g[1],g[2],g[3]) for g in GEARS[name]]:
        cs.append((x,y,tip(m,z)+0.0,z0,z1,'gear:'+g))
    if name in HAND_LEN:
        z0,z1=HAND_Z[name]; cs.append((x,y,HAND_LEN[name]+0.3,z0,z1,'hand'))
    return cs

def clash(cs_a, cs_b, name_a, name_b, mesh_pairs, margin=0.15):
    for (x1,y1,r1,a0,a1,t1) in cs_a:
        for (x2,y2,r2,b0,b1,t2) in cs_b:
