            d=np.hypot(x1-x2,y1-y2)
            if d < r1+r2+margin:
                if t1.startswith('gear:') and t2.startswith('gear:') and (t1[5:],t2[5:]) in mesh_pairs: continue
                return True
    return False

if __name__=='__main__':
    pass
