import numpy as np, random, json
from layout import *
random.seed(1)
O=np.array([0.,0.])
mesh_pairs=set()
for a,ga,b,gb in MESH: mesh_pairs.add((ga,gb)); mesh_pairs.add((gb,ga))
mesh_pairs.add(('Aw','Aw'))
def pol(c,d,ang): return np.array([c[0]+d*np.cos(ang), c[1]+d*np.sin(ang)])
def dd(n1,g1,n2,g2): return dist(n1,g1,n2,g2)
barrel=[(0,0,9.8,0,1.0,'drum'),(0,0,0.5,-1,1.6,'arb')]
def build(P,angs,sideA8):
    pos={'M':P}
    # A8, A6 intersections
    for nm,dO in (('A8',12.0),('A6',12.8)):
        d=np.hypot(*P); ex=(dO**2-7.5**2+d**2)/(2*d); h=np.sqrt(max(dO**2-ex**2,0))
        u=P/d; v=np.array([-u[1],u[0]])
        s= sideA8 if nm=='A8' else -sideA8
        pos[nm]=u*ex+v*h*s
    pos['I']=pol(P,6.0,angs[0]); pos['X1']=pol(P,4.2,angs[1])
    pos['X2']=pol(pos['X1'],4.8,angs[2]); pos['X3']=pol(pos['X2'],6.0,angs[3]); pos['S']=pol(pos['X3'],3.6,angs[4])
    pos['H']=P; pos['J']=pol(P,4.8,angs[5]); pos['D']=pol(pos['J'],7.2,angs[6])
    return pos
def score(pos, which):
    mobs=[m for m in pos if m not in ('A6','A8')]+[which]
    cyl={m:cylinders(m,pos[m]) for m in mobs}
    # barrel
    for m in mobs:
        if m==which: continue
        for c in cyl[m]:
            d=np.hypot(c[0],c[1])
            if d < 9.8+c[2]+0.2 and not (c[4]<=-0.05 or c[3]>=1.05 and False):
                if not(c[3]>=1.05): return False
    for m in cyl:
        if m!=which:
            for c in cyl[m]:
                pass
    for a,b in __import__('itertools').combinations(mobs,2):
        if clash(cyl[a],cyl[b],a,b,mesh_pairs): return False
    return True
best=None
for it in range(200000):
    P=np.array([-random.uniform(12,17), random.uniform(-4,4)])
    angs=[random.uniform(0,2*np.pi) for _ in range(7)]
    pos=build(P,angs,random.choice([1,-1]))
    # distance of non-A axes from barrel >= 10.9
    ok=all(np.hypot(*pos[m])>=10.9 for m in pos if m not in('A8','A6'))
    if not ok: continue
    if not (score(pos,'A8') and score(pos,'A6')): continue
    pts=[]
    # case centre best: minimise max extent
    allc=[]
    for m in pos:
        for c in cylinders(m,pos[m]):
            if c[5] in('gear:Aw',) or c[5].startswith('gear') or c[5] in ('hand','collar','tube'): allc.append((c[0],c[1],c[2]))
    allc.append((0,0,9.8))
    A=np.array(allc)
    # c on x-axis line or free: coarse grid
    bc=None
    for cx in np.linspace(-14,8,45):
      for cy in np.linspace(-8,8,33):
        if np.hypot(cx,cy)+9.8>20.4: continue
        ext=(np.hypot(A[:,0]-cx,A[:,1]-cy)+A[:,2]).max()
        if bc is None or ext<bc[0]: bc=(ext,cx,cy)
    if bc[0]<=19.8 and (best is None or bc[0]<best[0]):
        best=(bc[0],bc[1],bc[2],P.tolist(),angs,{k:v.tolist() for k,v in pos.items()})
        print(it,best[0],flush=True)
json.dump(best,open('best.json','w'))
print(best)
