            adj.setdefault(m['driver'],[]).append((m['driven'],m['driver_teeth'],m['driven_teeth']))
            adj.setdefault(m['driven'],[]).append((m['driver'],m['driven_teeth'],m['driver_teeth']))
        st=['barrel']
        while st:
            a=st.pop()
            for b,za,zb in adj.get(a,[]):
