    for di,d in enumerate(dirs):
        hf={}; moved={k:tr(m,d) for k,m in mv.mob.items()}
        direct={k:vol(moved[k],mv.frame)>0.01 for k in names}
        h=dict(direct)
        ch=True
        while ch:
            ch=False
            for a in names:
                if h[a]: continue
                for b in names:
                    if a==b or not h[b]: continue
                    if math.hypot(mv.axis[a][0]-mv.axis[b][0],mv.axis[a][1]-mv.axis[b][1])<=0.01:
                        if vol(moved[a],mv.mob[b])>0.01: h[a]=True; ch=True; break
        for k in names: out.setdefault(k,[]).append(h[k])
    return {k:v for k,v in out.items() if not all(v)}
def check3(mv):
    bad=[]
    for k,ps in mv.mparts.items():
        if k=='barrel' or len(ps)<2: continue
        for p in ps:
            others=K.union([part(q) for q in ps if q!=p])
