        if len(seen)!=n: bad.append((k,'not one piece'))
    return bad
def mesh_test(D,N,axD,axN,zD,zN,off=0.0,stride=1,verbose=False):
    """returns (ok, info). D,N manifolds; off: move N along centre line by off (positive away)."""
    axD=np.array(axD);axN=np.array(axN)
    u=axN-axD; dist=np.hypot(*u)
    if dist<1e-9: u=np.array([1.0,0.0])
    else: u=u/dist
    axN2=axN+u*off
    if off!=0: N=tr(N,(u[0]*off,u[1]*off,0))
    m=2*dist/(zD+zN)
    nsteps=8*max(zD,zN)
    info={'maxint':0,'maxgap':0,'minV':1e9,'minVH':1e9,'fail':[]}
    def pose(x):
        a=x*360/(8*zD)
        d=rotz(D,axD,a); n=rotz(N,axN2,-a*zD/zN)
        return d,n
    idx=range(0,nsteps,stride)
    for i in idx:
        d,n=pose(i)
        v=vol(d,n)
        info['maxint']=max(info['maxint'],v)
        if v>0.01: info['fail'].append(('jam',i,v)); 
        if i%4==0 and v==0 :
            g=K.min_distance(d,n,0.2)
            info['maxgap']=max(info['maxgap'],g)
            if g>0.1: info['fail'].append(('gap',i,g))
        if i%8==0:
            for f in (1/3,1/5):
                dd,nn=pose(i+f); v2=vol(dd,nn); info['maxint']=max(info['maxint'],v2)
                if v2>0.01: info['fail'].append(('jam+',i+f,v2))
            # teeth drive
            d0=d
            d1=rotz(D,axD,i*360/(8*zD)+90/zD)
            reg=(d1^n)-d0
            V=reg.volume()
            if V<=0: info['fail'].append(('drive0',i,V)); info['minV']=min(info['minV'],V);continue
            bb=reg.bounding_box(); H=bb[5]-bb[2]
            info['minV']=min(info['minV'],V); info['minVH']=min(info['minVH'],V/H/(0.5*m*m))
            if V<0.001 or V/H<=0.5*m*m: info['fail'].append(('drive',i,V,V/H,0.5*m*m))
    return (len(info['fail'])==0),info
