order=['I','X1','X2','X3','S','J','D']
def okp(m,pos,ctx):
    if np.hypot(*pos[m])<10.9: return False
    cm=cylinders(m,pos[m])
    for o in pos:
        if o==m or {o,m}=={'M','H'}: continue
        if o=='H': continue
        if clash(cm,ctx[o],m,o,mesh_pairs): return False
    return True
def run(P,sd,seed):
