    ctx['H']=cylinders('H',P)
    # A8 / A6 vs M ok? 
    def rec(i):
        if i==len(order): return True
        m=order[i]; par,d=parent[m]
        angs=list(np.radians(np.arange(0,360,4))); rnd.shuffle(angs)
        for a in angs:
            pos[m]=pol(pos[par],d,a)
            ctx[m]=cylinders(m,pos[m])
            # test vs all placed (incl A6 and A8 separately)
            good=True
            for o in list(pos):
                if o in (m,'H'): continue
                if {o,m}=={'M','H'}: continue
                if o in pos and o!=m and clash(ctx[m],ctx[o],m,o,mesh_pairs): good=False;break
            if good and np.hypot(*pos[m])<10.9: good=False
            if good and rec(i+1): return True
        del pos[m]; ctx.pop(m,None)
        return False
    ok=rec(0)
    return pos if ok else None
if __name__=='__main__':
