from wtests import *
mv=Mov('movement.json')
solid={n:part(n) for n in mv.fixed}
for k,v in mv.mparts.items():
    if k!='barrel':
        for p in v: solid[p]=part(p)
solid['barrel']=barrel()
A=json.load(open(ROOT+'/delivery/assembly.json'))
order=[];[order.append(n) for n in A['order'] if n in solid and n not in order]
